ALTER TABLE profiles ADD COLUMN IF NOT EXISTS location text, ADD COLUMN IF NOT EXISTS bio text, ADD COLUMN IF NOT EXISTS age integer, ADD COLUMN IF NOT EXISTS activity_type text, ADD COLUMN IF NOT EXISTS preferred_time text, ADD COLUMN IF NOT EXISTS pace text, ADD COLUMN IF NOT EXISTS interests text[], ADD COLUMN IF NOT EXISTS rating numeric DEFAULT 5.0, ADD COLUMN IF NOT EXISTS completed_pairings integer DEFAULT 0;
create table if not exists notifications ( id uuid default uuid_generate_v4() primary key, user_id uuid references profiles(id) on delete cascade not null, type text not null, title text not null, message text not null, link text, read boolean default false, created_at timestamp with time zone default timezone('utc'::text, now()) not null ); alter table notifications enable row level security; drop policy if exists "Users can access their own notifications" on notifications; create policy "Users can access their own notifications" on notifications for select using (auth.uid() = user_id); drop policy if exists "Users can update their own notifications" on notifications; create policy "Users can update their own notifications" on notifications for update using (auth.uid() = user_id); drop policy if exists "System can insert notifications" on notifications; create policy "System can insert notifications" on notifications for insert with check (true);
create or replace function public.create_new_event_notification() returns trigger as $$ begin insert into public.notifications (user_id, type, title, message, link) select id, 'activity', 'New Activity Near You', 'A new event: ' || new.title || ' has been created.', '/events/' || new.id from public.profiles where id != new.created_by; return new; end; $$ language plpgsql security definer; drop trigger if exists on_event_created on public.events; create trigger on_event_created after insert on public.events for each row execute procedure public.create_new_event_notification();
create or replace function public.create_joined_event_notification() returns trigger as $$ begin insert into public.notifications (user_id, type, title, message, link) select events.created_by, 'pairing', 'New Event Participant', (select name from public.profiles where id = new.user_id) || ' joined your event: ' || events.title, '/events/' || new.event_id from public.events where id = new.event_id and events.created_by != new.user_id; return new; end; $$ language plpgsql security definer; drop trigger if exists on_event_joined on public.user_events; create trigger on_event_joined after insert on public.user_events for each row execute procedure public.create_joined_event_notification();
